// Calendar View — Time Series, route: jsx
// Source: calendar_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

const MARGIN = { top: 6, right: 10, bottom: 10, left: 44 };
const WEEKS_PER_YEAR = 53;
const YEARS = [2021, 2022, 2023];
const WEEKDAY_INITIALS = ['M', 'T', 'W', 'T', 'F'];

/** One value per date; each date becomes a cell, colored on a diverging ramp. */
export type Data = { date: Date; value: number }[];

// Seeded PRNG so the series is byte identical on every render, reload and machine.
function mulberry32(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Weekdays only, so a year fits five rows the way a trading calendar does.
function buildSeries(): Data {
  const random = mulberry32(20260813);
  const start = new Date(Date.UTC(YEARS[0], 0, 1));
  const end = new Date(Date.UTC(YEARS[YEARS.length - 1] + 1, 0, 1));
  return d3
    .utcDays(start, end)
    .filter((date) => date.getUTCDay() !== 0 && date.getUTCDay() !== 6)
    .map((date) => ({ date, value: (random() + random() + random() - 1.5) * 0.024 }));
}

const dailyChanges = buildSeries();

export default function Calendar({ data = dailyChanges, width }: { data?: Data; width: number }) {
  const cellSize = (width - MARGIN.left - MARGIN.right) / WEEKS_PER_YEAR;
  const yearHeight = cellSize * 7;

  const years = useMemo(() => {
    const countDay = (day: number) => (day + 6) % 7; // Monday-first row index
    const weekOfYear = (date: Date) => d3.utcMonday.count(d3.utcYear(date), date);
    const formatDate = d3.utcFormat('%x');
    const formatMonth = d3.utcFormat('%b');
    const formatValue = d3.format('+.2%');

    // Symmetric domain clipped at the 99.75th percentile so a few spikes cannot flatten the ramp.
    const magnitude = d3.quantile(data, 0.9975, (d) => Math.abs(d.value)) ?? 0.05;
    const color = d3.scaleSequential(d3.interpolatePiYG).domain([-magnitude, magnitude]);

    // A month's left edge steps down one row on the weekday the month starts.
    const monthPath = (start: Date) => {
      const row = Math.max(0, Math.min(5, countDay(start.getUTCDay())));
      const week = weekOfYear(start);
      const head =
        row === 0
          ? `M${week * cellSize},0`
          : row === 5
            ? `M${(week + 1) * cellSize},0`
            : `M${(week + 1) * cellSize},0V${row * cellSize}H${week * cellSize}`;
      return `${head}V${5 * cellSize}`;
    };

    return d3.groups(data, (d) => d.date.getUTCFullYear()).map(([year, days]) => ({
      year,
      cells: days.map((d) => ({
        key: d.date.toISOString().slice(0, 10),
        x: weekOfYear(d.date) * cellSize + 0.5,
        y: countDay(d.date.getUTCDay()) * cellSize + 0.5,
        fill: color(d.value),
        title: `${formatDate(d.date)}  ${formatValue(d.value)}`
      })),
      months: d3
        .utcMonths(d3.utcMonth(days[0].date), days[days.length - 1].date)
        .map((month, i) => ({
          key: `${year}-${month.getUTCMonth()}`,
          label: formatMonth(month),
          labelX: weekOfYear(d3.utcMonday.ceil(month)) * cellSize + 2,
          // January needs no divider; it is already the left edge of the year.
          path: i === 0 ? null : monthPath(month)
        }))
    }));
  }, [cellSize, data]);

  const height = Math.round(yearHeight * years.length + MARGIN.top + MARGIN.bottom);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Calendar heatmap of simulated daily index changes for 2021 through 2023, one cell per weekday"
    >
      {years.map((year, i) => (
        <g
          key={year.year}
          transform={`translate(${MARGIN.left},${MARGIN.top + yearHeight * i + cellSize * 1.5})`}
        >
          <text
            x={-6}
            y={-5}
            textAnchor="end"
            fontWeight="bold"
            fontSize={cellSize * 0.9}
            fill="var(--text)"
          >
            {year.year}
          </text>
          {WEEKDAY_INITIALS.map((initial, row) => (
            <text
              key={row}
              x={-6}
              y={(row + 0.5) * cellSize}
              dy="0.31em"
              textAnchor="end"
              fontSize={cellSize * 0.62}
              fill="var(--muted)"
            >
              {initial}
            </text>
          ))}
          {year.cells.map((cell) => (
            <rect
              key={cell.key}
              x={cell.x}
              y={cell.y}
              width={cellSize - 1}
              height={cellSize - 1}
              fill={cell.fill}
            >
              <title>{cell.title}</title>
            </rect>
          ))}
          {year.months.map((month) => (
            <g key={month.key}>
              {month.path && (
                <path d={month.path} fill="none" stroke="var(--bg)" strokeWidth={2} />
              )}
              <text x={month.labelX} y={-5} fontSize={cellSize * 0.62} fill="var(--muted)">
                {month.label}
              </text>
            </g>
          ))}
        </g>
      ))}
    </svg>
  );
}
